parameters.jsCode:
// [B10] Both models failed on this question: a timeout, a refusal, an answer that did not fit the
// schema twice. The person still gets an answer — that it is going to a human — and the reason is
// recorded as model_failed rather than as "nothing found", because those are different problems with
// different fixes.
const ctx = $('Build context').first().json;
const err = $input.first().json || {};

return [{
  json: {
    ...ctx,
    outcome: 'escalate',
    reason: 'model_failed',
    confidence: 0,
    validation_detail: String(err.error?.message || err.message || 'both model attempts failed')
      .slice(0, 300),
  },
}];

// [B9] The node the whole case exists for. The model has answered; this decides whether anyone is
// allowed to see it.
//
// Three checks, all of them code. None of them ask the model anything, because a model that made a
// citation up will confirm it just as fluently.
//   1. An answer must cite something.
//   2. Every cited id must be one that was actually put in front of it.
//   3. Every quote must appear, word for word, in that chunk's text.
// A failure is not a retry and not a silent fix: the answer is thrown away and the question goes to
// a human with the reason recorded.
const ctx = $('Build context').first().json;
const model = $input.first().json;

// chainLlm puts the parsed object under `output` when a structured parser is attached; some versions
// hand back the object itself. Both shapes are accepted rather than assumed.
const parsed = model.output ?? model.json ?? model;
const outcome = String(parsed.outcome || '').toLowerCase();
const citations = Array.isArray(parsed.citations) ? parsed.citations : [];
const confidence = Number.isFinite(Number(parsed.confidence)) ? Number(parsed.confidence) : 0;

// A quote is looked for with flexible whitespace: a model that reflowed a line break has not made
// anything up, and failing it for that would be pedantry that costs real answers. The match returns
// the position IN THE ORIGINAL TEXT, because the section map is measured in original characters —
// comparing an index from the collapsed string against those offsets put one citation under the
// wrong heading before this was written this way.
const escape = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

function locate(text, quote) {
  const words = String(quote || '').trim().split(/\s+/).filter(Boolean);
  if (!words.length) return -1;
  const m = new RegExp(words.map(escape).join('\\s+'), 'i').exec(String(text || ''));
  return m ? m.index : -1;
}

function verify() {
  if (outcome === 'clarify') return { ok: true };
  if (outcome === 'escalate') return { ok: true };
  if (!citations.length) return { ok: false, reason: 'citation_mismatch', detail: 'answered with no citation' };

  for (const c of citations) {
    const chunk = ctx.allowed[c.chunk_id];
    if (!chunk) {
      return { ok: false, reason: 'citation_mismatch',
               detail: `cited ${c.chunk_id}, which was not in the context` };
    }
    if (locate(chunk.text, c.quote) < 0) {
      return { ok: false, reason: 'citation_mismatch',
               detail: `quote not found in ${c.chunk_id}: ${String(c.quote).slice(0, 80)}` };
    }
  }
  if (confidence < ctx.settings.confidence) {
    return { ok: false, reason: 'low_confidence', detail: `confidence ${confidence} < ${ctx.settings.confidence}` };
  }
  return { ok: true };
}

const verdict = verify();

// Which sub-section each quote sits in. The chunker recorded where every merged section starts, so a
// citation points at "Refunds / Monthly plans", not at the page.
function sectionOf(chunk, quote) {
  const i = locate(chunk.text, quote);
  if (i < 0 || !chunk.sections.length) return chunk.heading_path;
  let found = chunk.sections[0];
  for (const s of chunk.sections) if (s.at <= i) found = s;
  return found.title || chunk.heading_path;
}

const final = verdict.ok ? (outcome || 'escalate') : 'escalate';
const clarifyText = final === 'clarify' ? String(parsed.answer || parsed.question || '').trim() : '';

// Tried here once: turning a short question that did find documents into a clarifying question
// instead of a ticket, on the theory that asking is cheaper than a person. It was measured and
// reverted. "What is your uptime SLA?" is five words and perfectly specific, and the rule turned an
// honest "we have nothing on that" into "did you mean security, billing or limits?", which is worse
// than useless. Word count cannot tell vague from absent; the model can, and does, most of the time.

return [{
  json: {
    ...ctx,
    outcome: final,
    answer: final === 'answer' ? String(parsed.answer || '').trim() : '',
    clarify_question: clarifyText,
    confidence,
    reason: verdict.ok ? (final === 'escalate' ? (parsed.reason || 'model_escalated') : '') : verdict.reason,
    validation_detail: verdict.detail || '',
    citations: final === 'answer' ? citations.map((c) => {
      const chunk = ctx.allowed[c.chunk_id];
      return {
        chunk_id: c.chunk_id,
        quote: c.quote,
        doc_url: chunk.doc_url,
        doc_title: chunk.doc_title,
        section: sectionOf(chunk, c.quote),
      };
    }) : [],
  },
}];

// [B11] Every path that ends with a person comes through here: a question about someone's own
// account, an empty search, a low score, a citation that did not check out, a model that failed
// twice. The reason is recorded as a category rather than a sentence, because the distribution of
// reasons is the most useful number this system produces.
//
// nothing_found is not a defect in the agent. It is a hole in the documentation, and a week of those
// is a list of pages somebody should write.
const req = $input.first().json;
const ticket = `T-${Date.now().toString(36).slice(-5).toUpperCase()}`;

const found = (req.found || []).slice(0, 5);
const foundText = found.length
  ? found.map((f) => `${f.heading_path} (${f.doc_url}, ${f.score})`).join('\n')
  : 'nothing above the similarity threshold';

const REASON_TEXT = {
  always_human: 'about this customer\'s own account, money or legal position',
  nothing_found: 'nothing in the documents came close',
  low_confidence: 'the documents were close but did not answer it',
  citation_mismatch: 'the answer could not be backed by the documents it claimed',
  budget: 'the daily model budget was already spent',
  model_failed: 'the model failed twice in a row',
};

const reason = req.reason || 'nothing_found';

return [{
  json: {
    ...req,
    ticket,
    outcome: 'escalate',
    reason,
    ticket_body: {
      typecast: true,
      fields: {
        Ticket: ticket,
        Question: req.question,
        Reason: reason,
        Confidence: Math.round(Number(req.confidence || 0)),
        Found: [foundText, req.validation_detail ? `\n${req.validation_detail}` : ''].join(''),
        Status: 'New',
        Session: req.session_id,
        Created: new Date().toISOString(),
      },
    },
    // Telegram, in HTML: Markdown breaks on the first underscore in a url, which is a lesson from
    // the Lead -> CRM case rather than a guess.
    telegram_text: [
      `<b>${ticket}</b> — ${REASON_TEXT[reason] || reason}`,
      '',
      `<b>Question:</b> ${req.question.slice(0, 500)}`,
      found.length ? `<b>Closest:</b> ${found[0].heading_path} (${found[0].score})` : '',
      `<b>Session:</b> ${req.session_id}`,
    ].filter(Boolean).join('\n'),
  },
}];

// [B13] The last node before the person. It writes the reply, the sources under it, and the row that
// lets the next turn of this conversation make sense.
//
// Links are attached here and nowhere earlier: the model never saw a url, so it cannot have invented
// one. Each source points at the sub-section its quote came from.
// This node is reached from three places, and one of them lies about what it is handing over: the
// Telegram node replaces the item with its own API response, so a ticket arrives here as
// {ok: true, result: {...}}. When the input does not look like a request, the real one is read back
// from the ticket node. The try/catch is not decoration — asking n8n for a node that did not run in
// this branch throws.
function fromTicket() {
  try {
    return $('Build ticket').first().json;
  } catch (e) {
    return null;
  }
}

const incoming = $input.first().json || {};
const r = incoming.session_id ? incoming : (fromTicket() || incoming);

const PHRASES = {
  en: {
    unknown: 'I don\'t know — the documents have nothing on that. I have passed it to a person, '
      + 'who will answer here. Reference {ticket}.',
    empty: 'Ask me something about the product and I will look it up in the documentation.',
    sources: 'Sources',
  },
  uk: {
    unknown: 'Не знаю — у документах про це нічого немає. '
      + 'Передав людині, вона відповість тут. Звернення {ticket}.',
    empty: 'Запитайте про продукт — пошукаю в документації.',
    sources: 'Джерела',
  },
};
const say = PHRASES[r.lang] || PHRASES.en;

let text;
if (r.empty) text = say.empty;
else if (r.outcome === 'answer') text = r.answer;
else if (r.outcome === 'clarify') text = r.clarify_question;
else text = say.unknown.replace('{ticket}', r.ticket || '');

const sources = (r.citations || []).map((c) => ({
  title: c.doc_title,
  section: c.section,
  url: c.doc_url,
  quote: c.quote,
}));

return [{
  json: {
    record_id: r.record_id,
    reply: {
      session_id: r.session_id,
      outcome: r.outcome || (r.empty ? 'clarify' : 'escalate'),
      answer: text,
      sources,
      ticket: r.ticket || null,
      confidence: r.confidence ?? null,
      // The eval harness reads these; a person never sees them.
      debug: r.is_eval ? { reason: r.reason || '', best_score: r.best_score ?? null,
                           found: r.found || [], quarantined_lines: r.quarantined_lines ?? 0 } : undefined,
    },
    // One upsert instead of a lookup and a write: Airtable merges on Session.
    conversation_body: {
      typecast: true,
      performUpsert: { fieldsToMergeOn: ['Session'] },
      records: [{
        fields: {
          Session: r.session_id,
          Channel: r.is_eval ? 'eval' : (r.channel || 'web'),
          Started: r.asked_at,
          Turns: r.turns || 1,
          'Last question': r.question,
          'Last outcome': r.outcome || 'clarify',
          'Last answer': text.slice(0, 5000),
          // Which documents this answer stood on. The next short reply in this session leans on
          // them, so "and monthly?" keeps talking about refunds instead of drifting into pricing.
          'Last sources': [...new Set(sources.map((s) => s.url))].join('\n'),
        },
      }],
    },
  },
}];

const html = "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Support</title>
<style>
  :root {
    color-scheme: light dark;
    --bg: #ffffff; --fg: #1b1b1b; --muted: #6b6b6b; --line: #e3e3e3;
    --mine: #f1f3f5; --source: #f7f8f9; --accent: #2f6f4f;
  }
  @media (prefers-color-scheme: dark) {
    :root { --bg: #16181a; --fg: #e9e9e9; --muted: #9a9a9a; --line: #2a2d30;
            --mine: #212528; --source: #1c1f22; --accent: #7fc0a0; }
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--fg);
         font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
  main { max-width: 720px; margin: 0 auto; padding: 24px 16px 140px; }
  header { border-bottom: 1px solid var(--line); padding-bottom: 12px; margin-bottom: 20px; }
  h1 { font-size: 17px; margin: 0 0 2px; font-weight: 600; }
  header p { margin: 0; color: var(--muted); font-size: 13px; }
  .turn { margin: 18px 0; }
  .q { background: var(--mine); border-radius: 12px; padding: 10px 14px; display: inline-block;
       max-width: 85%; }
  .a { margin-top: 12px; white-space: pre-wrap; }
  .sources { margin-top: 14px; border-top: 1px solid var(--line); padding-top: 10px; }
  .sources h2 { font-size: 12px; text-transform: uppercase; letter-spacing: .06em;
                color: var(--muted); margin: 0 0 8px; font-weight: 600; }
  .source { background: var(--source); border-left: 2px solid var(--accent); border-radius: 0 8px 8px 0;
            padding: 8px 12px; margin-bottom: 8px; }
  .source .where { font-size: 13px; font-weight: 600; }
  .source .quote { font-size: 13px; color: var(--muted); margin-top: 3px; }
  .ticket { font-size: 13px; color: var(--muted); margin-top: 10px; }
  .thinking { color: var(--muted); font-size: 14px; }
  form { position: fixed; bottom: 0; left: 0; right: 0; background: var(--bg);
         border-top: 1px solid var(--line); padding: 14px 16px; }
  .row { max-width: 720px; margin: 0 auto; display: flex; gap: 8px; }
  input { flex: 1; padding: 11px 14px; border: 1px solid var(--line); border-radius: 10px;
          background: var(--bg); color: var(--fg); font: inherit; }
  input:focus { outline: 2px solid var(--accent); outline-offset: -1px; }
  button { padding: 11px 18px; border: 0; border-radius: 10px; background: var(--accent);
           color: #fff; font: inherit; font-weight: 600; cursor: pointer; }
  button:disabled { opacity: .5; cursor: default; }
</style>
</head>
<body>
<main>
  <header>
    <h1>Support</h1>
    <p>Answers come from the documentation, with the place they came from underneath.</p>
  </header>
  <div id="thread"></div>
</main>

<form id="form">
  <div class="row">
    <input id="q" autocomplete="off" placeholder="Ask about the product&hellip;" autofocus>
    <button id="send" type="submit">Ask</button>
  </div>
</form>

<script>
  // Relative on purpose: the page is served by the same n8n that answers, so it works on localhost,
  // behind a tunnel and behind a reverse proxy without anything being configured twice.
  var ASK = "../webhook/ask".replace("../", "/");
  // Substituted when the workflow is deployed. Anyone who can open this page can read it — which is
  // the honest cost of a page with no login, and it is written down in LIMITATIONS.md.
  var SECRET = "__WEBHOOK_SECRET__";
  // One session for as long as this tab is open: enough for a follow-up like "and monthly?" to be
  // understood, and it disappears with the tab.
  var SESSION = "web-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);

  var thread = document.getElementById("thread");
  var form = document.getElementById("form");
  var input = document.getElementById("q");
  var send = document.getElementById("send");

  function el(tag, cls, text) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (text !== undefined) n.textContent = text;
    return n;
  }

  // Enter submits. A form with one text input and a submit button does this on its own in every
  // browser — except when the keystroke is synthetic, which is how this page is tested. Three lines
  // to make both paths identical is cheaper than a demo where the obvious key sometimes does nothing.
  input.addEventListener("keydown", function (e) {
    if (e.key !== "Enter" || e.shiftKey || e.isComposing) return;
    e.preventDefault();
    if (form.requestSubmit) form.requestSubmit();
    else form.dispatchEvent(new Event("submit", { cancelable: true }));
  });

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var question = input.value.trim();
    if (!question) return;
    input.value = "";
    send.disabled = true;

    var turn = el("div", "turn");
    turn.appendChild(el("div", "q", question));
    var pending = el("div", "a thinking", "Looking it up…");
    turn.appendChild(pending);
    thread.appendChild(turn);
    window.scrollTo(0, document.body.scrollHeight);

    fetch(ASK, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-webhook-secret": SECRET },
      body: JSON.stringify({ question: question, session_id: SESSION, channel: "web" })
    })
      .then(function (r) { return r.json(); })
      .then(function (reply) {
        turn.removeChild(pending);
        turn.appendChild(el("div", "a", reply.answer || ""));

        if (reply.sources && reply.sources.length) {
          var box = el("div", "sources");
          box.appendChild(el("h2", null, "Sources"));
          reply.sources.forEach(function (s) {
            var item = el("div", "source");
            item.appendChild(el("div", "where", s.section || s.title));
            item.appendChild(el("div", "quote", "“" + s.quote + "”"));
            box.appendChild(item);
          });
          turn.appendChild(box);
        }
        if (reply.ticket) {
          turn.appendChild(el("div", "ticket", "Passed to a person · " + reply.ticket));
        }
      })
      .catch(function (err) {
        turn.removeChild(pending);
        turn.appendChild(el("div", "a", "Could not reach the agent: " + err.message));
      })
      .then(function () {
        send.disabled = false;
        input.focus();
        window.scrollTo(0, document.body.scrollHeight);
      });
  });
</script>
</body>
</html>
";
return [{ json: { html } }];
